/// Return the current `amount` of `kind` on `uid`'s power list, or 0 if the
/// creature has no such power. Bead `sts2-rs-bm34f`; only tests read it now.
#[cfg(test)]
pub(crate) fn power_amount_on_creature(
    state: &CombatState,
    uid: CreatureUid,
    kind: PowerKind,
) -> i32 {
    let Some(creature) = state.creatures.iter().find(|c| c.id == uid.0) else {
        return 0;
    };
    for puid in &creature.powers {
        if let Some(p) = state.powers.get_by_id(puid.0) {
            if p.kind == kind {
                return p.amount;
            }
        }
    }
    0
}

