/// Look up a [`CardId`]'s rarity by scanning every per-character
/// `CardSpec` slice. Returns `None` when no slice contains a matching
/// factory (e.g. for ids whose spec lives outside the canonical
/// generated pools — character placeholders, debug-only ids). O(N)
/// over ~400 specs; only called from rare-rarity-gated card bodies
/// (Anointed, ...) so the cost is acceptable.
pub(crate) fn card_rarity_for_id(id: CardId) -> Option<crate::cards::types::CardRarity> {
    use crate::cards::spec_index::{
        COLORLESS_SPECS, DEFECT_SPECS, IRONCLAD_SPECS, NECROBINDER_SPECS, REGENT_SPECS,
        SILENT_SPECS, STATUS_SPECS,
    };
    // Must cover EVERY character pool: Anointed's C# filter is
    // `Draw.Cards.Where(c => c.Rarity == Rare)`, so a Regent/Necrobinder Rare
    // sitting in the draw pile has to resolve too. Omitting REGENT_SPECS /
    // NECROBINDER_SPECS made `card_rarity_for_id` return `None` for those
    // cards, so Anointed found zero rares and pulled nothing on those
    // characters (PILE_COUNT|ANOINTED: e.g. Regent BOMBARDMENT/BUNDLE_OF_JOY/
    // HEAVENLY_DRILL never reached hand). Bead `sts2-rs-6ynt.8` follow-up.
    let slices: &[&[fn() -> CardSpec]] = &[
        IRONCLAD_SPECS,
        SILENT_SPECS,
        DEFECT_SPECS,
        REGENT_SPECS,
        NECROBINDER_SPECS,
        COLORLESS_SPECS,
        STATUS_SPECS,
    ];
    for slice in slices {
        for &factory in *slice {
            let spec = factory();
            if spec.id == id {
                return Some(spec.rarity);
            }
        }
    }
    None
}

/// [`card_rarity_for_id`] in game build `version` (GH #793): v0.107.1 is
/// exactly [`card_rarity_for_id`]; v0.111.0 reads that build's rarity.
pub(crate) fn card_rarity_for_id_in(
    id: CardId,
    version: sts2_core::GameVersion,
) -> Option<crate::cards::types::CardRarity> {
    if crate::cards::v0111::is_v0111(version) {
        crate::cards::spec_index::rarity_for_card_id_in(id, version)
    } else {
        card_rarity_for_id(id)
    }
}

/// Internal helper: present the draw-pile cards whose Card POD's
/// `card_type` equals `kind` as a player choice and add the chosen one
/// to hand. Mirrors C# `SecretTechnique`/`SecretWeapon`
/// `CardSelectCmd.FromCombatPile(pile: Draw, filter: type)` `prefs(1)`
/// (a player pick, consuming no `RunRngSet` stream):
///   * 0 candidates → no-op (no card to fetch);
///   * exactly 1 (`num <= MinSelect`) → auto-add, no prompt, no sort;
///   * 2+ → open a single-pick
///     [`AddFromDrawByType`](sts2_core::ChoiceKind::AddFromDrawByType)
///     choice (`legal_actions` enumerates one option per candidate and
///     auto-resolves to option 0; MCTS explores all).
///
/// C# `FromCombatPile` (`CardSelectCmd.cs:404-410`, v0.107.1) does
/// `list = list.OrderBy(c => c.Rarity).ThenBy(c => c.Id)` for a Draw pile
/// BEFORE the selector takes its prefix, so the auto-resolved option 0
/// (and the replayed/MCTS option ORDER the parity harness asserts against)
/// must be the `(CardRarity ordinal, Entry name)`-minimal candidate, not
/// the raw draw-pile-order first. Without this sort a deck with 2+ same-type
/// cards moved a DIFFERENT card to hand than C#, desyncing a subsequent
/// Catastrophe `StableShuffle` (`PILE_COUNT|CATASTROPHE`, seed 1490). The
/// `OrderBy`/`ThenBy` is LINQ-stable → stable `sort_by`; and unlike
/// Catastrophe's own StableShuffle it carries NO `upgraded` tiebreak.
/// `card_rarity_rank_csharp` is the C# `CardRarity` ordinal.
///
/// Bead `sts2-rs-1xmxp` — replaces the prior random `state.rng` stub
/// (the `NOTE(sts2-rs-sr3ql)` "stays on legacy rng" caveat is now
/// resolved: this is a player choice in C#, not an RNG draw).
pub(crate) fn move_card_from_draw_to_hand_by_type(
    state: &mut CombatState,
    kind: sts2_core::cards::CardType,
) {
    let mut candidates: SmallVec<[sts2_core::CardUid; 16]> = state
        .player
        .draw
        .iter()
        .copied()
        // C# filters `c.Type == kind`; the Quest cards are `CardType.Quest`
        // (`Dowsing.cs:45`), so Secret Technique never fetches them.
        .filter(|uid| state.cards[uid.0.get() as usize - 1].card_type == kind)
        .collect();
    // Mirror C# `FromCombatPile`'s `OrderBy(Rarity).ThenBy(Id)` Draw-pile
    // sort (stable, no `upgraded` key). Harmless for the 0/1-candidate arms.
    candidates.sort_by(|a, b| {
        let ca = &state.cards[a.0.get() as usize - 1];
        let cb = &state.cards[b.0.get() as usize - 1];
        crate::cards::spec_index::card_rarity_rank_csharp_in(ca.card_id, state.game_version)
            .cmp(&crate::cards::spec_index::card_rarity_rank_csharp_in(
                cb.card_id,
                state.game_version,
            ))
            .then_with(|| {
                sts2_core::cards::draw_select_tiebreak(&state.cards, *a, *b, state.game_version)
            })
    });
    match candidates.as_slice() {
        [] => {}
        [uid] => {
            // FirstOrDefault: exactly one candidate, no prompt. C#
            // `CardPileCmd.Add(card, Hand)` (`SecretTechnique.cs:25`,
            // `SecretWeapon.cs:25`) sends it to the discard pile instead
            // when the hand already holds 10 cards (`CardPileCmd.cs:485-489`),
            // which an auto-play from the draw pile (Mayhem) can reach.
            if let Some(pos) = state.player.draw.iter().position(|u| u == uid) {
                let card = state.player.draw.remove(pos);
                // A pinned draw card leaves no stale pin behind, as the
                // multi-candidate select resolution does (#1105).
                sts2_core::cards::unpin(&mut state.player, card);
                let _ = sts2_core::cards::try_add_to_hand(&mut state.player, card);
            }
        }
        _ => {
            let options: Vec<sts2_core::ChoiceOption> = candidates
                .iter()
                .map(|uid| {
                    let idx = uid.0.get() as usize - 1;
                    sts2_core::ChoiceOption {
                        card_id: state.cards[idx].card_id,
                        upgraded: state.cards[idx].upgraded,
                        card_uid: Some(*uid),
                        source_pile: Some(sts2_core::cards::PileKind::Draw),
                    }
                })
                .collect();
            state.request_card_choice(
                sts2_core::ChoiceKind::AddFromDrawByType,
                options,
                1,
                1,
                false,
            );
        }
    }
}

