/// Sample `count` colorless cards WITH replacement from
/// `COLORLESS_SPECS` and mint them into `state.cards`. Mirrors Python
/// `combat.generate_colorless_cards` — character-independent pool, no
/// distinctness constraint (`[create_card(rng.choice(colorless_ids))
/// for _ in range(count)]` at
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py:2182`). The Python
/// `generation_context="modifier"` filter is approximated as "any card
/// in `COLORLESS_SPECS`" — same shortcut as the `ut1v` / `fa2o`
/// trampolines. Bead `sts2-rs-7xih`.
/// Sample `count` **distinct** colorless cards from the filtered
/// `ColorlessCardPool` combat pool (C# `CardFactory.GetDistinctForCombat`):
/// a whole-pool `UnstableShuffle` over the `combat_card_generation` rng, then
/// take `count`. Spawns the chosen ids into the arena and returns their uids
/// (the caller routes them into a pile). Reuses
/// [`distinct_colorless_modifier_ids`] for the shuffle+take (same 50-card
/// pool / read count), then materialises each id at base (non-upgraded), the
/// way `CardFactory.CreateCard` does. Used by SpectrumShiftPower's
/// `BeforeHandDraw` body.
pub fn sample_distinct_colorless_cards_for_hook(
    state: &mut CombatState,
    count: usize,
) -> SmallVec<[CardUid; 4]> {
    let ids = distinct_colorless_modifier_ids(state, count);
    let mut uids: SmallVec<[CardUid; 4]> = SmallVec::with_capacity(ids.len());
    for id in ids {
        if let Some(mut card) = crate::cards::spec_index::card_pod_from_id(id, false) {
            let raw = u32::try_from(state.cards.len() + 1).expect("cards arena fits in u32");
            let uid = CardUid::new(raw).expect("non-zero uid");
            card.uid = uid;
            // v0.111.0 card values (GH #793).
            card.normalize_for_version(state.game_version);
            state.cards.push(card);
            uids.push(uid);
        }
    }
    uids
}

pub fn sample_colorless_cards_for_hook(
    state: &mut CombatState,
    count: usize,
) -> SmallVec<[CardUid; 4]> {
    use crate::cards::spec_index::COLORLESS_SPECS;

    if count == 0 || COLORLESS_SPECS.is_empty() {
        return SmallVec::new();
    }
    let mut uids: SmallVec<[CardUid; 4]> = SmallVec::with_capacity(count);
    for _ in 0..count {
        if COLORLESS_SPECS.is_empty() {
            break;
        }
        let factory = COLORLESS_SPECS[state
            .rng
            .next_int_exclusive(0, COLORLESS_SPECS.len() as i32)
            as usize];
        let spec = factory();
        let mut card = card_from_spec(&spec);
        let raw = u32::try_from(state.cards.len() + 1).expect("cards arena fits in u32");
        let uid = CardUid::new(raw).expect("non-zero uid");
        card.uid = uid;
        // v0.111.0 card values (GH #793).
        card.normalize_for_version(state.game_version);
        state.cards.push(card);
        uids.push(uid);
    }
    uids
}

pub(crate) fn create_character_ethereal_cards_into_arena(
    state: &mut CombatState,
    character: sts2_core::potions::CharacterId,
    count: usize,
) -> SmallVec<[CardUid; 4]> {
    if count == 0 {
        return SmallVec::new();
    }
    // C# `BigHat.AfterSideTurnStart` (BigHat.cs:21-33): the character pool's
    // Ethereal cards, then `CardFactory.GetDistinctForCombat`
    // (CardFactory.cs:119-130) = `FilterForPlayerCount` + `FilterForCombat`
    // + `TakeRandom` (an `UnstableShuffle` on `CombatCardGeneration`). That
    // is the fight's combat-generatable pool restricted to Ethereal, for
    // every character: Regent and Necrobinder used to return nothing
    // (PARITY95 Necrobinder: no Big Hat cards, so a C#-played Lethality was
    // missing in Rust), and the other three sampled the unfiltered slice.
    let pool: SmallVec<[CardSpec; 96]> = fight_pool(state, character)
        .iter()
        .filter(|s| s.is_ethereal())
        .copied()
        .collect();
    if pool.is_empty() {
        return SmallVec::new();
    }
    let mut shuffled = pool;
    state
        .run_rng
        .combat_card_generation
        .shuffle_for(state.game_version, shuffled.as_mut_slice());
    let chosen: SmallVec<[CardSpec; 4]> = shuffled.into_iter().take(count).collect();
    let mut uids: SmallVec<[CardUid; 4]> = SmallVec::with_capacity(chosen.len());
    for spec in chosen {
        let mut card = card_from_spec(&spec);
        let raw = u32::try_from(state.cards.len() + 1).expect("cards arena fits in u32");
        let uid = CardUid::new(raw).expect("non-zero uid");
        card.uid = uid;
        // C# `CardModel.DeckVersion == null` marker for combat-generated
        // cards (see core `spawn_card_into_pile`). Bead `sts2-rs-a4096`.
        card.set_combat_var(sts2_core::cards::VarKey::GeneratedInCombat, 1);
        // v0.111.0 card values (GH #793).
        card.normalize_for_version(state.game_version);
        state.cards.push(card);
        uids.push(uid);
    }
    uids
}

/// The character's **combat-generatable** card pool, in the order and
/// membership C# uses for `CardFactory.GetDistinctForCombat` /
/// `GetForCombat` over `Owner.Character.CardPool` — i.e. after
/// `GetUnlockedCards` + `FilterForCombat` (drop Basic/Ancient/Event
/// rarity, `!CanBeGeneratedInCombat`, and — single-player —
/// `MultiplayerOnly`). Ironclad uses the canonical 78-card filtered pool
/// (`ironclad_combat_generatable_specs`); Silent uses the 79-card filtered
/// pool (`silent_combat_generatable_specs`). Defect isn't validated against
/// C# yet and still uses its raw generated slice (unfiltered) — TODO build
/// its filtered pool the same way. Bead `sts2-rs-q6bix`.
///
/// GH #367: the C# call this models is `GetUnlockedCards`
/// (`CardPoolModel.cs:83-96`), whose FIRST step is
/// `FilterThroughEpochs(unlockState, AllCards)` — cards behind an unrevealed
/// epoch never reach `FilterForCombat`. When
/// [`crate::unlocks::any_locked`] is false (the default, and what the C#
/// headless oracle builds) this is the identity and the original memoized
/// path runs untouched; a non-empty locked set takes the generation-keyed
/// path below.
pub(crate) fn combat_generatable_pool(
    character: sts2_core::potions::CharacterId,
) -> &'static [CardSpec] {
    use std::sync::OnceLock;

    use sts2_core::potions::CharacterId;

    if crate::unlocks::any_locked() {
        return locked_filtered_combat_pool(character);
    }

    // The pool is a pure function of `character` (spec constructors +
    // static filters — no state / RNG), but it was being rebuilt from the
    // per-card spec constructors on EVERY combat card-generation event —
    // thousands of times per MCTS search on decks with generator cards
    // (~1.1% of instructions on the 2026-07-03 realistic-deck callgrind).
    // Memoize per character; the borrow is `'static`, so callers filter /
    // copy from the cached slice without reconstruction.
    static POOLS: [OnceLock<SmallVec<[CardSpec; 96]>>; 5] = [
        OnceLock::new(),
        OnceLock::new(),
        OnceLock::new(),
        OnceLock::new(),
        OnceLock::new(),
    ];
    let slot = match character {
        CharacterId::Ironclad => &POOLS[0],
        CharacterId::Silent => &POOLS[1],
        CharacterId::Defect => &POOLS[2],
        CharacterId::Necrobinder => &POOLS[3],
        CharacterId::Regent => &POOLS[4],
    };
    slot.get_or_init(|| build_combat_generatable_pool(character))
}

/// `character`'s generation pool in THIS fight: [`combat_generatable_pool_in`]
/// solo, and with teammates its co-op counterpart, which keeps the
/// `MultiplayerOnly` cards (C# `FilterForPlayerCount`, GH #991). Every
/// in-combat character-pool generation reads this.
pub(crate) fn fight_pool(
    state: &CombatState,
    character: sts2_core::potions::CharacterId,
) -> &'static [CardSpec] {
    use crate::cards::pool_order::{coop_combat_pool, is_multiplayer, Pool};
    if is_multiplayer(state) {
        coop_combat_pool(Pool::Character(character), state.game_version)
    } else {
        combat_generatable_pool_in(character, state.game_version)
    }
}

/// The colorless generation pool in THIS fight, as ids:
/// [`colorless_combat_generatable_card_ids`] solo, its co-op counterpart with
/// teammates (see [`fight_pool`]).
pub(crate) fn fight_colorless_ids(state: &CombatState) -> SmallVec<[CardId; 72]> {
    use crate::cards::pool_order::{coop_combat_pool, is_multiplayer, Pool};
    if is_multiplayer(state) {
        coop_combat_pool(Pool::Colorless, state.game_version)
            .iter()
            .map(|s| s.id)
            .collect()
    } else {
        colorless_combat_generatable_ids_in(state.game_version)
    }
}

/// [`colorless_combat_generatable_card_ids`] in game build `version`:
/// v0.113.0 adds MyShinies right after MindBlast (`ColorlessCardPool.cs:62-63`;
/// it can be generated in combat and is not multiplayer-only).
pub(crate) fn colorless_combat_generatable_ids_in(
    version: sts2_core::GameVersion,
) -> SmallVec<[CardId; 72]> {
    let mut ids = SmallVec::from_slice(colorless_combat_generatable_card_ids());
    if version >= sts2_core::GameVersion::V0_113_0 {
        if let Some(at) = ids.iter().position(|&id| id == CardId::MindBlast) {
            ids.insert(at + 1, CardId::MyShinies);
        }
    }
    ids
}

/// [`combat_generatable_pool`] in game build `version` (GH #793): the
/// v0.107.1 pool with each slot moved onto that build's card and values
/// ([`crate::cards::v0111::pool_spec_of`]: Sidestep in Scare's Silent slot,
/// Outbreak a Skill, …) and the cards the build flagged
/// `CanBeGeneratedInCombat => false` dropped (Eidolon, Nightmare,
/// Transfigure). Pool order is kept — C# filters with `Where`. Sidestep is
/// the only card the build adds to a single-player character pool, so this
/// map + filter over the v0.107.1 pool is the whole difference.
pub(crate) fn combat_generatable_pool_in(
    character: sts2_core::potions::CharacterId,
    version: sts2_core::GameVersion,
) -> &'static [CardSpec] {
    use std::collections::BTreeMap;
    use std::sync::{OnceLock, RwLock};

    use sts2_core::potions::CharacterId;

    if !crate::cards::v0111::is_v0111(version) {
        return combat_generatable_pool(character);
    }
    fn build(
        character: sts2_core::potions::CharacterId,
        version: sts2_core::GameVersion,
    ) -> Vec<CardSpec> {
        combat_generatable_pool(character)
            .iter()
            .map(|s| crate::cards::v0111::pool_spec_of(*s, version))
            .filter(|s| crate::cards::v0111::can_be_generated_in_combat(s.id, version))
            .collect()
    }
    if crate::unlocks::any_locked() {
        // Same generation-keyed leak as `locked_filtered_combat_pool`.
        static CACHE: RwLock<Option<(u64, BTreeMap<u8, &'static [CardSpec]>)>> = RwLock::new(None);
        let generation = crate::unlocks::locked_generation();
        let key = character as u8;
        if let Some((gen, map)) = CACHE.read().expect("pool cache poisoned").as_ref() {
            if *gen == generation {
                if let Some(slice) = map.get(&key) {
                    return slice;
                }
            }
        }
        let leaked: &'static [CardSpec] = Box::leak(build(character, version).into_boxed_slice());
        let mut guard = CACHE.write().expect("pool cache poisoned");
        match guard.as_mut() {
            Some((gen, map)) if *gen == generation => {
                map.insert(key, leaked);
            }
            _ => {
                let mut map = BTreeMap::new();
                map.insert(key, leaked);
                *guard = Some((generation, map));
            }
        }
        return leaked;
    }
    static POOLS: [OnceLock<Vec<CardSpec>>; 5] = [
        OnceLock::new(),
        OnceLock::new(),
        OnceLock::new(),
        OnceLock::new(),
        OnceLock::new(),
    ];
    let slot = match character {
        CharacterId::Ironclad => &POOLS[0],
        CharacterId::Silent => &POOLS[1],
        CharacterId::Defect => &POOLS[2],
        CharacterId::Necrobinder => &POOLS[3],
        CharacterId::Regent => &POOLS[4],
    };
    slot.get_or_init(|| build(character, version))
}

/// The epoch-filtered variant of [`combat_generatable_pool`], reached only
/// when a locked set is installed (GH #367).
///
/// Cached per `(character, unlocks generation)` and leaked, so callers still
/// get a `'static` slice and a repeated lookup costs one `RwLock` read. The
/// leak is bounded by the number of DISTINCT lock-sets a process installs —
/// one in every real deployment, and a handful in tests.
///
/// Ordering matters as much as membership: `UnstableShuffle` reads `len - 1`
/// ints, so dropping a card changes both which card is picked AND the
/// `combat_card_generation` cursor. Filtering AFTER the pool is built in
/// `GenerateAllCards()` order preserves the relative order of the survivors,
/// which is what C#'s `List.RemoveAll` does too.
fn locked_filtered_combat_pool(character: sts2_core::potions::CharacterId) -> &'static [CardSpec] {
    use std::collections::BTreeMap;
    use std::sync::RwLock;

    static CACHE: RwLock<Option<(u64, BTreeMap<u8, &'static [CardSpec]>)>> = RwLock::new(None);

    let generation = crate::unlocks::locked_generation();
    let key = character as u8;
    if let Some((gen, map)) = CACHE.read().expect("pool cache poisoned").as_ref() {
        if *gen == generation {
            if let Some(slice) = map.get(&key) {
                return slice;
            }
        }
    }
    let built: Vec<CardSpec> = build_combat_generatable_pool(character)
        .into_iter()
        .filter(|s| !crate::unlocks::is_card_locked(s.id))
        .collect();
    let leaked: &'static [CardSpec] = Box::leak(built.into_boxed_slice());
    let mut guard = CACHE.write().expect("pool cache poisoned");
    match guard.as_mut() {
        Some((gen, map)) if *gen == generation => {
            map.insert(key, leaked);
        }
        // Stale (or absent) generation: start a fresh map. The slices the old
        // map held stay leaked — bounded, and dropping them would dangle the
        // `'static` borrows already handed out.
        _ => {
            let mut map = BTreeMap::new();
            map.insert(key, leaked);
            *guard = Some((generation, map));
        }
    }
    leaked
}

/// Uncached pool construction — see [`combat_generatable_pool`] for the
/// memoizing entry point (and the semantics doc-comment above it).
fn build_combat_generatable_pool(
    character: sts2_core::potions::CharacterId,
) -> SmallVec<[CardSpec; 96]> {
    use sts2_core::potions::CharacterId;

    use crate::cards::spec_index::{DEFECT_SPECS, NECROBINDER_SPECS, REGENT_SPECS};

    let pool: SmallVec<[CardSpec; 96]> = match character {
        CharacterId::Ironclad => crate::cards::ironclad::specs::ironclad_combat_generatable_specs()
            .into_iter()
            .collect(),
        CharacterId::Silent => crate::cards::silent::specs::silent_combat_generatable_specs()
            .into_iter()
            .collect(),
        // Defect: the full DEFECT_SPECS pool (in `GenerateAllCards()`
        // alphabetical order), filtered by C# `FilterForCombat`
        // (CardFactory.cs:121-124) — drop Basic / Ancient / Event rarity and
        // any `CanBeGeneratedInCombat => false` card. Without this filter the
        // pool wrongly carried the Basic STRIKE_DEFECT / DEFEND_DEFECT /
        // DUALCAST / ZAP plus the Ancient BIASED_COGNITION / QUADCAST, which
        // both shifted the `UnstableShuffle` outcome (wrong card picked by
        // WHITE_NOISE / DISCOVERY / the Skill/Power/Attack potions) AND skewed
        // the `combat_card_generation` read count (the shuffle reads ~pool-len
        // ints), desyncing the stream for every later draw. Mirrors the
        // Ironclad / Silent / Necrobinder pools.
        CharacterId::Defect => DEFECT_SPECS
            .iter()
            .map(|f| f())
            .filter(|s| {
                use crate::cards::types::CardRarity;
                !matches!(
                    s.rarity,
                    CardRarity::Basic | CardRarity::Ancient | CardRarity::Event
                ) && card_can_be_generated_in_combat(s.id)
            })
            .collect(),
        // Necrobinder: the full NECROBINDER_SPECS pool, filtered to the
        // combat-generatable rarities (C# `FilterForCombat` drops Basic /
        // Ancient / Event; the leftover rarities are Common/Uncommon/Rare).
        // The pool is now COMPLETE (88/88 cards, in `GenerateAllCards()`
        // alphabetical order), so the picked-card identity and the
        // `combat_card_generation` read count (an UnstableShuffle reads
        // ~pool-len ints) match C# — `CallOfTheVoidPower.BeforeHandDraw`
        // generation is byte-faithful.
        CharacterId::Necrobinder => NECROBINDER_SPECS
            .iter()
            .map(|f| f())
            .filter(|s| {
                use crate::cards::types::CardRarity;
                !matches!(
                    s.rarity,
                    CardRarity::Basic | CardRarity::Ancient | CardRarity::Event
                )
            })
            .collect(),
        // Regent: the full REGENT_SPECS pool (88 cards, in `GenerateAllCards()`
        // alphabetical order = `RegentCardPool.cs`), filtered by C#
        // `FilterForCombat` + single-player `FilterForPlayerCount`:
        //   - rarity ∉ {Basic, Ancient, Event} → drops StrikeRegent /
        //     DefendRegent (Basic);
        //   - `CanBeGeneratedInCombat => false` → drops Royalties
        //     (`Royalties.cs`);
        //   - `MultiplayerConstraint => MultiplayerOnly` → drops HammerTime,
        //     Largesse (`HammerTime.cs` / `Largesse.cs`; also enforced by the
        //     generic `card_is_multiplayer_only` post-filter below).
        // The order + membership match C#, so an `UnstableShuffle` / `NextItem`
        // pick over this pool reads the same `combat_card_generation` ints and
        // lands on the same card as the headless oracle.
        CharacterId::Regent => REGENT_SPECS
            .iter()
            .map(|f| f())
            .filter(|s| {
                use crate::cards::types::CardRarity;
                !matches!(
                    s.rarity,
                    CardRarity::Basic | CardRarity::Ancient | CardRarity::Event
                ) && !matches!(
                    s.id,
                    CardId::RoyaltiesCard | CardId::HammerTime | CardId::Largesse
                )
            })
            .collect(),
    };
    // C# `CardFactory.FilterForPlayerCount` (CardFactory.cs:24-31): in
    // singleplayer (`Players.Count == 1`, the only mode here) drop every
    // `MultiplayerConstraint == MultiplayerOnly` card. For Defect that
    // removes ENERGY_SURGE + IGNITION, shrinking the combat-generatable
    // pool from 82 to C#'s 80 and fixing the `combat_card_generation`
    // read-count desync that WHITE_NOISE / DISCOVERY / OROBIC_ACID / the
    // typed potions inherited. Applied to every character pool for
    // faithfulness. Bead `sts2-rs-91tc1`.
    pool.into_iter()
        .filter(|s| !card_is_multiplayer_only(s.id))
        .collect()
}

/// Cards whose C# model sets `MultiplayerConstraint => MultiplayerOnly`,
/// so `CardFactory.FilterForPlayerCount` drops them from every
/// singleplayer generation pool (CardFactory.cs:24-31). Full v0.103.2 set
/// (grep `MultiplayerOnly` under Models.Cards). Only ids present in the
/// Rust spec slices matter; extend as ports land. Defect membership:
/// ENERGY_SURGE + IGNITION.
pub(crate) fn card_is_multiplayer_only(id: CardId) -> bool {
    matches!(
        id,
        CardId::BeaconOfHope
            | CardId::BelieveInYou
            | CardId::CoordinateCard
            | CardId::DemonicShield
            | CardId::EnergySurge
            | CardId::Flanking
            | CardId::GangUp
            | CardId::GlimpseBeyond
            | CardId::HammerTime
            | CardId::HuddleUp
            | CardId::Ignition
            | CardId::InterceptCard
            | CardId::Knockdown
            | CardId::Largesse
            | CardId::LegionOfBone
            | CardId::Lift
            | CardId::Mimic
            | CardId::Rally
            | CardId::SneakyCard
            | CardId::TagTeam
            | CardId::TankCard
    ) || crate::cards::spec_index::is_multiplayer_only(id)
}

/// Transform the card at `card_uid` into a random card from its
/// transform-options pool, in place. Trampoline matching
/// [`sts2_core::card_effects::TransformToRandomFn`], installed by
/// [`crate::cards::dispatch::install_default_registry`] so the
/// `EntropyPower.after_player_turn_start` body in core can transform
/// hand cards without a workspace dep on `sts2-content`.
///
/// Mirrors C# `CardCmd.TransformToRandom(card, Rng.CombatCardSelection)`
/// → `CardFactory.CreateRandomCardForTransform`:
///   pool = `GetFilteredTransformationOptions(original, original.Pool
///          .GetUnlockedCards(...), isInCombat: true)`
///        = combat-generatable pool, already rarity {Common,Uncommon,Rare}
///          + `CanBeGeneratedInCombat` + (single-player) non-`MultiplayerOnly`,
///          MINUS the original card's own id;
///   pick = `rng.NextItem(pool)` = `pool[NextInt(0, len)]` off the
///          `CombatCardSelection` stream.
///
/// **Pool resolution:** C# keys the pool on `original.Pool` (the
/// transformed card's own colour), and `GetFilteredTransformationOptions`
/// applies the Common/Uncommon/Rare rarity filter ONLY when the original
/// is not Status/Curse (`(uint)(rarity - 8) > 1u`):
///
/// * **Status original** (e.g. a Strangler-spat SLIMED picked by
///   Entropy): pool = `StatusCardPool.GenerateAllCards()` order
///   [Beckon, Burn, Dazed, Debris, FranticEscape, Infection, Slimed,
///   Soot, Toxic, Void, Wound], `CanBeGeneratedInCombat` drops
///   FranticEscape + Soot, NO rarity filter, minus the original id.
///   The prior port fell through to the character pool and rolled an
///   Ironclad common (coverage `card:ENTROPY` hand_ids[0] cs=BECKON
///   rs=ANGER). Bead `sts2-rs-01ygn`.
/// * **Curse original** (e.g. SPORE_MIND picked by Entropy): pool =
///   `CurseCardPool.GenerateAllCards()` order, `CanBeGeneratedInCombat`
///   drops AscendersBane, NO rarity filter, minus the original id
///   (GH #1054 item 7).
/// * **Other originals**: the *original card's own* character pool —
///   resolved from its id via [`crate::cards::spec_index::character_for_card_id`]
///   to mirror C# `CardModel.Pool` (the colour pool that lists the id,
///   independent of the deck owner). For a same-colour card this IS the
///   player's pool; for a CROSS-CHARACTER original that entered the deck
///   legitimately (e.g. a Silent MEMENTO_MORI pulled into an Ironclad deck
///   by SPLASH) it is the card's home pool, so the replacement is drawn
///   from Silent — not Ironclad (parity sweep seed 2180: Rust→UNMOVABLE vs
///   C#→TOOLS_OF_THE_TRADE). Colourless / Curse / Status / Token / Event /
///   Ancient originals are handled by the dedicated branches above. Bead
///   `sts2-rs-isooo` (q6bix ENTROPY; cross-character pool fix).
pub fn transform_card_to_random_for_hook(
    state: &mut CombatState,
    card_uid: CardUid,
) -> Option<CardUid> {
    use crate::cards::types::CardRarity;

    let original_id = state.cards.iter().find(|c| c.uid == card_uid)?.card_id;
    let rarity = crate::cards::spec_index::rarity_for_card_id_in(original_id, state.game_version);
    // C# `CardFactory.GetDefaultTransformationOptions`:
    //   pool = (Type != Quest && Rarity not in {Event,Ancient,Token})
    //              ? original.Pool : ColorlessCardPool
    // then `GetFilteredTransformationOptions` keeps Common/Uncommon/Rare
    // UNLESS the original is itself Curse/Status (those skip the rarity
    // filter), keeps `CanBeGeneratedInCombat`, and excludes the original id —
    // throwing (→ headless swallows → no transform) when the result is empty.
    // Bead `sts2-rs-3tder`:
    //  * an ANCIENT/EVENT original (e.g. BREAK) is FORCED onto the colorless
    //    pool, so it transforms into a colorless Common/Uncommon/Rare card
    //    (fuzz seed 4819: BREAK → JACKPOT vs RS's character-pool FLAME_BARRIER).
    //  * a CURSE original resolves to the CurseCardPool (Curse branch below).
    //    Its combat-generatable set is NOT empty: the prior port returned
    //    `None` here (no transform, zero RNG reads), so Entropy left a hand
    //    SPORE_MIND untouched where C# rolls DECAY (GH #1054 item 7, Regent
    //    seed 1008, THE_KIN_BOSS).
    // Detect a genuinely-colorless original via the authoritative full
    // `COLORLESS_SPECS` set (64 cards) rather than the narrower
    // `is_colorless_card_id` list, which omitted several colorless ids.
    // v0.111.0: TheBall is listed by `ColorlessCardPool` (decomp
    // ColorlessCardPool.cs:85), so its `original.Pool` is the colorless pool
    // (CardFactory.cs:173). It lives in `V0111_ONLY_SPECS`, not
    // `COLORLESS_SPECS`, so it fell through to the player's character pool
    // (Entropy on a Silent hand TheBall rolled KNIFE_TRAP where C# rolls the
    // colorless PREP_TIME). The id exists in no v0.107.1 state.
    // v0.113.0 adds MyShinies (Rare) to the same pool, and its spec also
    // lives outside `COLORLESS_SPECS`. Reading the build's
    // `ColorlessCardPool.GenerateAllCards()` list covers every such card.
    let is_colorless_original = crate::cards::spec_index::COLORLESS_SPECS
        .iter()
        .any(|f| f().id == original_id)
        || crate::cards::pool_order::generate_all_cards(
            crate::cards::pool_order::Pool::Colorless,
            state.game_version,
        )
        .contains(&original_id);
    // Quest / Event / Ancient / **Token** originals are FORCED onto the
    // ColorlessCardPool by C#
    // (`(Type != Quest && Rarity not in {Event,Ancient,Token}) ? Pool :
    // ColorlessCardPool`, CardFactory.cs:173). Every Quest-TYPE card
    // (ByrdonisEgg, LanternKey, SpoilsMap, Dowsing) is also `CardRarity.Quest`
    // and no other card is, so the rarity stands in for the type: Entropy on SPOILS_MAP rolls the colorless pool (random-loadout
    // v0.107.1 seed 1198: C# FINESSE, not the character pool's DARK_EMBRACE).
    // The Token arm is the
    // fix for bead `sts2-rs-p52dg`: the per-combat token cards (GiantRock,
    // Shiv, Soul, the Regent minion cards, …) were mis-tagged `Status` and
    // fell into the StatusCardPool branch below, so Entropy transformed a
    // hand GIANT_ROCK into a status card (BECKON) instead of the colorless
    // card C# rolls (AUTOMATION). With the spec rarity corrected to `Token`,
    // they take this branch and the Common/Uncommon/Rare colorless pool
    // (`GetFilteredTransformationOptions` applies the rarity filter for a
    // Token original — Token is not Status/Curse). Seeds 3872/4610
    // (→AUTOMATION), 2281 (→PROLONG), 6016 (→VOLLEY).
    let use_colorless_pool = is_colorless_original
        || matches!(
            rarity,
            Some(CardRarity::Quest | CardRarity::Ancient | CardRarity::Event | CardRarity::Token)
        );
    let pool: SmallVec<[CardSpec; 96]> = if matches!(rarity, Some(CardRarity::Status)) {
        use crate::cards::status_specs_generated as st;
        // C# `StatusCardPool.GenerateAllCards()` order; FranticEscape and
        // Soot override `CanBeGeneratedInCombat => false` and are dropped
        // by the in-combat filter. Wither does NOT override it (Wither.cs),
        // so it stays in the in-combat pool — omitting it dropped the list
        // to length 9 vs C#'s 10, so `Rng.NextItem`'s length-dependent index
        // selected the wrong card (Entropy transforms: sweep seeds
        // 2763/3842/3965/4932).
        [
            st::beckon,
            st::burn,
            st::dazed,
            st::debris,
            st::infection,
            st::wither,
            st::slimed,
            st::toxic,
            st::void,
            st::wound,
        ]
        .iter()
        .map(|f| f())
        .filter(|s| s.id != original_id)
        .collect()
    } else if matches!(rarity, Some(CardRarity::Curse)) {
        use crate::cards::status_specs_generated as st;
        // C# `CurseCardPool.GenerateAllCards()` order (CurseCardPool.cs:20-40,
        // identical in v0.107.1 / v0.111.0). `GetFilteredTransformationOptions`
        // skips the rarity filter for Status/Curse (CardFactory.cs,
        // `(uint)(rarity - 8) > 1u`) and keeps `CanBeGeneratedInCombat`; no
        // curse has a multiplayer constraint. AscendersBane (listed first)
        // overrides `CanBeGeneratedInCombat => false` only in v0.111.0
        // (AscendersBane.cs:10); v0.107.1 overrides just
        // `CanBeGeneratedByModifiers`, so it stays in the in-combat pool there
        // (random-loadout v0.107.1 seeds 1008 / 1163). Minus the original id
        // that leaves 17 (v0.107.1) / 16 (v0.111.0).
        let keep_ascenders_bane = state.game_version < sts2_core::GameVersion::V0_111_0;
        [
            st::ascenders_bane,
            st::bad_luck,
            st::clumsy,
            st::curse_of_the_bell,
            st::debt,
            st::decay,
            st::doubt,
            st::enthralled,
            st::folly,
            st::greed,
            st::guilty,
            st::injury,
            st::normality,
            st::poor_sleep,
            st::regret,
            st::shame,
            st::spore_mind,
            st::writhe,
        ]
        .iter()
        .map(|f| f())
        .filter(|s| keep_ascenders_bane || s.id != CardId::AscendersBane)
        .filter(|s| s.id != original_id)
        .collect()
    } else if use_colorless_pool {
        // C# `GetDefaultTransformationOptions` keys the pool on
        // `original.Pool` — for a colorless original that is the
        // `ColorlessCardPool`, NOT the player's character pool (and for an
        // Event/Ancient original it is FORCED to the colorless pool). The
        // prior port fell through to the character branch and rolled an
        // Ironclad common when Entropy/etc. transformed such a card (fuzz
        // seed 1154: Prolong → cs=AUTOMATION rs=ANGER; seed 4819: BREAK →
        // JACKPOT vs FLAME_BARRIER). The combat-generatable colorless pool
        // (`GetUnlockedCards` + Common/Uncommon/Rare + `CanBeGeneratedInCombat`,
        // C# alphabetical order) minus the original id is exactly
        // [`colorless_combat_generatable_card_ids`] minus self. Beads
        // `sts2-rs-isooo` / `sts2-rs-3tder`.
        fight_colorless_ids(state)
            .into_iter()
            .filter(|&id| id != original_id)
            .filter_map(crate::cards::spec_index::spec_for_card_id)
            .collect()
    } else {
        // C# `CardFactory.GetDefaultTransformationOptions` keys the pool on
        // `original.Pool` — the transformed card's OWN colour pool, NOT the
        // player's character pool. They coincide for a same-colour card (the
        // common case), but DIVERGE for a cross-character original that
        // legitimately entered the deck — e.g. a Silent card pulled into an
        // Ironclad deck by SPLASH (`Splash` injects attacks from other
        // characters' pools). C# `CardModel.Pool` resolves to whichever pool
        // lists the card's id, independent of the deck owner, so MEMENTO_MORI
        // (Silent) transforms off the SILENT pool (→ TOOLS_OF_THE_TRADE),
        // while the prior port used the player's Ironclad pool (→ UNMOVABLE).
        // Surfaced by parity sweep seed 2180 (Ironclad, PHROG_PARASITE_ELITE):
        // divergent hand by turn 8. Bead `sts2-rs-isooo`.
        //
        // Resolve the original's home character; only fall back to the
        // player's character when the id isn't owned by any character slice
        // (defensive — non-colorless/status/curse/token originals are always
        // character-owned).
        let character = crate::cards::spec_index::character_for_card_id(original_id)
            .or(state.player.character)?;
        fight_pool(state, character)
            .iter()
            .copied()
            .filter(|s| s.id != original_id)
            .collect()
    };
    if pool.is_empty() {
        return None;
    }
    // The only caller is EntropyPower: v0.113.0 rolls on
    // `CombatCardGeneration` (decomp EntropyPower.cs:31), before that on
    // `CombatCardSelection`.
    let rng = if state.game_version >= sts2_core::GameVersion::V0_113_0 {
        &mut state.run_rng.combat_card_generation
    } else {
        &mut state.run_rng.combat_card_selection
    };
    let idx = rng.next_int_exclusive(0, pool.len() as i32) as usize;
    let replacement = card_from_spec(&pool[idx]);
    sts2_core::card_effects::transform_card_in_place(state, card_uid, replacement)
}

pub(crate) fn create_character_cards_into_arena(
    state: &mut CombatState,
    character: sts2_core::potions::CharacterId,
    count: usize,
    card_type: Option<sts2_core::cards::CardType>,
    distinct: bool,
) -> SmallVec<[CardUid; 4]> {
    create_filtered_character_cards_into_arena(state, character, count, card_type, None, distinct)
}

/// [`create_character_cards_into_arena`] with an additional **rarity** filter,
/// for the one C# generator that narrows the pool by rarity rather than by
/// card type: `HelloWorldPower.BeforeHandDraw` (`HelloWorldPower.cs:21-29`,
/// GH #636), whose LINQ reads `where c.Rarity == CardRarity.Common`.
///
/// The rarity narrowing happens BEFORE the shuffle, exactly as in C# — the
/// `Where` clause is applied to the pool handed to `GetDistinctForCombat`, and
/// `TakeRandom` is an `UnstableShuffle` over whatever list it receives. So the
/// filter changes both WHICH cards can be drawn and HOW MANY ints come off
/// `combat_card_generation` (roughly the filtered length). Filtering after the
/// shuffle, or not at all, desyncs the stream for every later roll in the
/// combat.
///
/// `rarity: None` is the unfiltered behaviour every other caller wants.
pub(crate) fn create_filtered_character_cards_into_arena(
    state: &mut CombatState,
    character: sts2_core::potions::CharacterId,
    count: usize,
    card_type: Option<sts2_core::cards::CardType>,
    rarity: Option<crate::cards::types::CardRarity>,
    distinct: bool,
) -> SmallVec<[CardUid; 4]> {
    if count == 0 {
        return SmallVec::new();
    }
    // References, not copies: the shuffle and the picks read only the pool's
    // length and order, and copying every spec was a measurable share of a
    // search (Infernal Blade et al. in playouts).
    let pool: SmallVec<[&CardSpec; 96]> = fight_pool(state, character)
        .iter()
        .filter(|s| card_type.is_none_or(|kt| s.card_type == kt))
        .filter(|s| rarity.is_none_or(|r| s.rarity == r))
        .collect();
    if pool.is_empty() {
        return SmallVec::new();
    }
    let chosen: SmallVec<[&CardSpec; 4]> = if distinct {
        let mut shuffled = pool;
        state
            .run_rng
            .combat_card_generation
            .shuffle_for(state.game_version, shuffled.as_mut_slice());
        shuffled.into_iter().take(count).collect()
    } else {
        (0..count)
            .map(|_| {
                pool[state
                    .run_rng
                    .combat_card_generation
                    .next_int_exclusive(0, pool.len() as i32) as usize]
            })
            .collect()
    };
    let mut uids: SmallVec<[CardUid; 4]> = SmallVec::with_capacity(chosen.len());
    for spec in chosen {
        let mut card = card_from_spec(spec);
        let raw = u32::try_from(state.cards.len() + 1).expect("cards arena fits in u32");
        let uid = CardUid::new(raw).expect("non-zero uid");
        card.uid = uid;
        // C# `CardModel.DeckVersion == null` marker for combat-generated
        // cards (see core `spawn_card_into_pile`). Bead `sts2-rs-a4096`.
        card.set_combat_var(sts2_core::cards::VarKey::GeneratedInCombat, 1);
        // v0.111.0 card values (GH #793).
        card.normalize_for_version(state.game_version);
        state.cards.push(card);
        uids.push(uid);
    }
    uids
}

/// Pick up to `count` **distinct** character [`CardId`]s from
/// `character`'s spec pool, drawn off the `combat_card_generation`
/// stream (C# `Rng.CombatCardGeneration`). When `card_type` is
/// `Some(kt)` the pool is filtered to that type (AttackPotion /
/// SkillPotion / PowerPotion); `None` keeps the whole combat-generatable
/// pool (`Discovery`). Returns the candidate ids **without** spawning any
/// card — the caller opens an `AddGeneratedFreeToHand` choice and only
/// the chosen id is materialised at resolve time. Mirrors C#
/// `CardFactory.GetDistinctForCombat(pool, count, Rng.CombatCardGeneration)`.
/// A character with no pool slice returns empty. Bead `sts2-rs-91tc1`.
pub(crate) fn distinct_character_card_ids(
    state: &mut CombatState,
    character: sts2_core::potions::CharacterId,
    card_type: Option<sts2_core::cards::CardType>,
    count: usize,
) -> SmallVec<[CardId; 4]> {
    if count == 0 {
        return SmallVec::new();
    }
    let mut pool: SmallVec<[CardId; 96]> = fight_pool(state, character)
        .iter()
        .filter(|s| card_type.is_none_or(|kt| s.card_type == kt))
        .map(|s| s.id)
        .collect();
    if pool.is_empty() {
        return SmallVec::new();
    }
    state
        .run_rng
        .combat_card_generation
        .shuffle_for(state.game_version, pool.as_mut_slice());
    pool.into_iter().take(count).collect()
}

/// Cards whose C# model overrides `CanBeGeneratedInCombat => false`,
/// so `CardFactory.FilterForCombat` drops them from every in-combat
/// generation pool even when their rarity qualifies. Full v0.103.2
/// set (grep `CanBeGeneratedInCombat => false`): Alchemize,
/// Disintegration, Feed, FranticEscape, HandOfGreed, HiddenGem,
/// MindRot, NeowsFury, NotYet, Royalties, Sloth, Soot, TheHunt,
/// WasteAway (GH #991 completed the list; the co-op pools of
/// [`crate::cards::pool_order`] filter every pool through it). Bead `sts2-rs-z4jsg` (card:SPLASH —
/// `THE_HUNT` was the lone membership delta once all four
/// cross-character pools were wired). Sibling of the rarity filter in
/// [`distinct_cross_character_attack_ids`].
pub(crate) fn card_can_be_generated_in_combat(id: CardId) -> bool {
    !matches!(
        id,
        CardId::Alchemize
            | CardId::Disintegration
            | CardId::Feed
            | CardId::FranticEscape
            | CardId::HandOfGreed
            | CardId::HiddenGem
            | CardId::MindRot
            | CardId::NeowsFury
            | CardId::NotYet
            | CardId::RoyaltiesCard
            | CardId::SlothStatus
            | CardId::Soot
            | CardId::TheHunt
            | CardId::WasteAway
    )
}

/// Pick up to `count` **distinct** Attack [`CardId`]s drawn from every
/// character pool **other than** the owner's, off the
/// `combat_card_generation` stream. Mirrors C# `Splash.OnPlay`:
/// [decompiled C# omitted — see the cited path]
/// `CharacterCardPools` enumerates `ModelDb.AllCharacters` in declared
/// order — **Ironclad, Silent, Regent, Necrobinder, Defect**
/// (ModelDb.cs:88-95) — minus the owner's pool; each pool contributes
/// its cards in `GenerateAllCards` (alphabetical) order, which the
/// `*_SPECS` slices mirror. Eligibility is C# `FilterForCombat`
/// (CardFactory.cs:121-124): `Type == Attack`, rarity ∉
/// {Basic, Ancient, Event}, and `CanBeGeneratedInCombat` (TheHunt is
/// the one cross-pool Attack flagged false). For an Ironclad player
/// that is exactly 24 + 29 + 32 + 28 = 113 candidates — matching C#'s
/// 112 `combat_card_generation` reads (`GetDistinctForCombat` →
/// `TakeRandom` = `UnstableShuffle` over the full list, then take 3).
/// Returns ids **without** spawning; the caller opens an
/// `AddGeneratedFreeToHand` choice. Built directly from the spec
/// slices (NOT [`combat_generatable_pool`], whose per-character arms
/// carry caller-specific filtering). Bead `sts2-rs-6ynt.8-splash` /
/// `sts2-rs-z4jsg`; coverage-sweep `card:SPLASH`.
pub(crate) fn distinct_cross_character_attack_ids(
    state: &mut CombatState,
    count: usize,
) -> SmallVec<[CardId; 4]> {
    use crate::cards::spec_index::{DEFECT_SPECS, NECROBINDER_SPECS, REGENT_SPECS, SILENT_SPECS};
    use crate::cards::types::CardRarity;
    use sts2_core::potions::CharacterId;

    if count == 0 {
        return SmallVec::new();
    }
    fn eligible(s: &CardSpec) -> bool {
        s.card_type == sts2_core::cards::CardType::Attack
            && !matches!(
                s.rarity,
                CardRarity::Basic | CardRarity::Ancient | CardRarity::Event
            )
            && card_can_be_generated_in_combat(s.id)
    }

    let own = state.player.character;
    let coop = crate::cards::pool_order::is_multiplayer(state);
    let mut pool: SmallVec<[CardId; 128]> = SmallVec::new();
    if coop {
        // Co-op (GH #991): the other characters' co-op pools, in the same
        // `ModelDb.AllCharacters` order.
        use crate::cards::pool_order::{coop_combat_pool, Pool};
        for ch in [
            CharacterId::Ironclad,
            CharacterId::Silent,
            CharacterId::Regent,
            CharacterId::Necrobinder,
            CharacterId::Defect,
        ] {
            if Some(ch) == own {
                continue;
            }
            pool.extend(
                coop_combat_pool(Pool::Character(ch), state.game_version)
                    .iter()
                    .filter(|s| s.card_type == sts2_core::cards::CardType::Attack)
                    .map(|s| s.id),
            );
        }
    } else if own != Some(CharacterId::Ironclad) {
        for s in crate::cards::ironclad::specs::ironclad_combat_generatable_specs() {
            if eligible(&s) {
                pool.push(s.id);
            }
        }
    }
    let slices: [(CharacterId, &[fn() -> CardSpec]); 4] = [
        (CharacterId::Silent, SILENT_SPECS),
        (CharacterId::Regent, REGENT_SPECS),
        (CharacterId::Necrobinder, NECROBINDER_SPECS),
        (CharacterId::Defect, DEFECT_SPECS),
    ];
    for (ch, slice) in slices {
        if coop || Some(ch) == own {
            continue;
        }
        for f in slice {
            let s = f();
            if eligible(&s) {
                pool.push(s.id);
            }
        }
    }
    if pool.is_empty() {
        return SmallVec::new();
    }
    state
        .run_rng
        .combat_card_generation
        .shuffle_for(state.game_version, pool.as_mut_slice());
    pool.into_iter().take(count).collect()
}

/// Pick up to `count` **distinct** colorless-modifier [`CardId`]s off
/// the `combat_card_generation` stream, **without** spawning. Mirrors
/// the distinct branch of [`create_colorless_modifier_cards`] but
/// returns ids for an `AddGeneratedFreeToHand` choose-a-card screen
/// (ColorlessPotion). Bead `sts2-rs-91tc1`.
pub(crate) fn distinct_colorless_modifier_ids(
    state: &mut CombatState,
    count: usize,
) -> SmallVec<[CardId; 4]> {
    // ColorlessPotion draws from the FULL ColorlessCardPool combat pool
    // (50, C# `GetDistinctForCombat`), NOT the smaller "modifier" subset.
    // Bead `sts2-rs-q6bix`.
    let mut shuffled = fight_colorless_ids(state);
    if count == 0 || shuffled.is_empty() {
        return SmallVec::new();
    }
    state
        .run_rng
        .combat_card_generation
        .shuffle_for(state.game_version, shuffled.as_mut_slice());
    shuffled.into_iter().take(count).collect()
}

/// JackOfAllTrades pool: distinct ids off the FULL ColorlessCardPool
/// combat-generatable pool **excluding JackOfAllTrades itself**, matching
/// C# `JackOfAllTrades.OnPlay`:
/// ```text
/// GetDistinctForCombat(Owner,
///     from c in ColorlessCardPool.GetUnlockedCards(...)
///     where !(c is JackOfAllTrades) select c,
///     Cards.IntValue, Rng.CombatCardGeneration)
/// ```
/// The `where !(c is JackOfAllTrades)` strips self BEFORE
/// `GetDistinctForCombat`'s shuffle, so the shuffled pool is the 50-card
/// [`colorless_combat_generatable_card_ids`] minus JackOfAllTrades = **49**
/// (consuming 48 `combat_card_generation` reads). The prior port drew from
/// the 18-card [`eligible_colorless_modifier_card_ids`] subset — wrong
/// membership AND read count (17 vs 48), desyncing the stream. Bead
/// `sts2-rs-q6bix`.
pub(crate) fn distinct_jack_of_all_trades_ids(
    state: &mut CombatState,
    count: usize,
) -> SmallVec<[CardId; 4]> {
    distinct_colorless_ids_except(state, count, Some(CardId::JackOfAllTrades))
}

/// `count` distinct cards of the whole combat-generatable colorless pool,
/// C# `CardFactory.GetDistinctForCombat(player, ColorlessCardPool…, count,
/// Rng.CombatCardGeneration)` with no filter: Largesse.
pub(crate) fn distinct_colorless_combat_ids(
    state: &mut CombatState,
    count: usize,
) -> SmallVec<[CardId; 4]> {
    distinct_colorless_ids_except(state, count, None)
}

fn distinct_colorless_ids_except(
    state: &mut CombatState,
    count: usize,
    except: Option<CardId>,
) -> SmallVec<[CardId; 4]> {
    if count == 0 {
        return SmallVec::new();
    }
    let mut shuffled: SmallVec<[CardId; 72]> = fight_colorless_ids(state)
        .into_iter()
        .filter(|&id| Some(id) != except)
        .collect();
    if shuffled.is_empty() {
        return SmallVec::new();
    }
    state
        .run_rng
        .combat_card_generation
        .shuffle_for(state.game_version, shuffled.as_mut_slice());
    shuffled.into_iter().take(count).collect()
}

/// `Enlightenment` cost cap (`min(held.cost, 1)` in the Python pin
/// at status.py:631). Cards with cost <= 1 are untouched (matches
/// `min`).
pub const ENLIGHTENMENT_COST_CAP: i8 = 1;

/// C# `MadScience.skillBlock` — block gained in Skill mode
/// (`MadScience.cs:25`). Distinct from the spec `base_block` (0), which is
/// unused because the default-constructed card is an Attack.
pub(crate) const MAD_SCIENCE_SKILL_BLOCK: i32 = 8;

/// TinkerTime rider effect for MadScience. Variant order mirrors
/// `MegaCrit.Sts2.Core.Models.Events/TinkerTime.cs::RiderEffect` (v0.103.2)
/// exactly so the packed encoding round-trips against the C# enum. Bead
/// `sts2-rs-eykwi`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TinkerTimeRider {
    None,
    Sapping,
    Violence,
    Choking,
    Energized,
    Wisdom,
    Chaos,
    Expertise,
    Curious,
    Improvement,
}

impl TinkerTimeRider {
    pub(crate) fn from_u8(v: u8) -> Self {
        match v {
            1 => Self::Sapping,
            2 => Self::Violence,
            3 => Self::Choking,
            4 => Self::Energized,
            5 => Self::Wisdom,
            6 => Self::Chaos,
            7 => Self::Expertise,
            8 => Self::Curious,
            9 => Self::Improvement,
            _ => Self::None,
        }
    }

    pub(crate) fn to_u8(self) -> u8 {
        match self {
            Self::None => 0,
            Self::Sapping => 1,
            Self::Violence => 2,
            Self::Choking => 3,
            Self::Energized => 4,
            Self::Wisdom => 5,
            Self::Chaos => 6,
            Self::Expertise => 7,
            Self::Curious => 8,
            Self::Improvement => 9,
        }
    }

    /// Resolve a wire spelling of C#'s `TinkerTime.RiderEffect` enum name.
    /// Case-insensitive; unknown spellings return `None` (the caller decides
    /// whether that is a hard error or "no rider"). This is the ingest half of
    /// the `MadScience.TinkerTimeRider` `[SavedProperty]`
    /// (`../sts2-wiki/decompiled/v0.107.1/MegaCrit.Sts2.Core.Models.Cards/MadScience.cs:125-137`).
    #[must_use]
    pub fn from_wire_name(name: &str) -> Option<Self> {
        Some(match name.trim().to_ascii_lowercase().as_str() {
            "none" => Self::None,
            "sapping" => Self::Sapping,
            "violence" => Self::Violence,
            "choking" => Self::Choking,
            "energized" => Self::Energized,
            "wisdom" => Self::Wisdom,
            "chaos" => Self::Chaos,
            "expertise" => Self::Expertise,
            "curious" => Self::Curious,
            "improvement" => Self::Improvement,
            _ => return None,
        })
    }
}

/// Pack a MadScience `(mode, rider)` into a single `i32`: `mode_idx << 4 |
/// rider`. `mode_idx`: Attack=0, Skill=1, Power=2.
pub(crate) fn pack_tinker_time(mode: CardType, rider: TinkerTimeRider) -> i32 {
    let mode_idx = match mode {
        CardType::Skill => 1,
        CardType::Power => 2,
        _ => 0,
    };
    (mode_idx << 4) | i32::from(rider.to_u8())
}

/// Set the per-instance TinkerTime mode + rider on a MadScience card,
/// packed into its `VarKey::Generic` slot. The TinkerTime event
/// (`sts2-rs-2guyj`) calls this when creating the granted card. Applied to
/// the master_deck card, the packing is run-persistent: deck cards are
/// cloned fresh into each combat (`run_bridge::enter_combat`) and the run
/// side never resets their vars, so the morph survives combat boundaries.
/// Bead `sts2-rs-eykwi` / `sts2-rs-2guyj`.
///
/// Also stamps the instance's `card_type` / `target_type`, because in C# both
/// are DERIVED from the variant rather than fixed by the spec:
/// `MadScience.cs:80` `Type => TinkerTimeType` and `:82-92`
/// `TargetType => TinkerTimeType != Attack ? Self : AnyEnemy`. The registry
/// spec is the default-constructed `MadScience(1, CardType.Attack, …,
/// AnyEnemy)` (`MadScience.cs:167-170`), so without this a Power-mode
/// MadScience stayed an Attack for every card-type-gated surface — including
/// `CuriousPower`'s own Power-card discount and the engine's targeting
/// legality.
pub fn set_mad_science_variant(
    card: &mut sts2_core::cards::Card,
    mode: CardType,
    rider: TinkerTimeRider,
) {
    use sts2_core::cards::TargetType;
    card.set_combat_var(VarKey::Generic, pack_tinker_time(mode, rider));
    card.card_type = mode;
    card.target_type = if mode == CardType::Attack {
        TargetType::Enemy
    } else {
        TargetType::Self_
    };
}

/// Decode the `(mode, rider)` packed into a MadScience card's
/// `VarKey::Generic` slot. `0` (unset) → `(Attack, None)`, matching C#'s
/// default-constructed `MadScience(1, CardType.Attack, …, AnyEnemy)`.
#[must_use]
pub fn mad_science_variant_of(card: &sts2_core::cards::Card) -> (CardType, TinkerTimeRider) {
    let packed = card.combat_var(VarKey::Generic);
    let mode = match packed >> 4 {
        1 => CardType::Skill,
        2 => CardType::Power,
        _ => CardType::Attack,
    };
    (mode, TinkerTimeRider::from_u8((packed & 0xF) as u8))
}

/// [`mad_science_variant_of`] for the MadScience currently resolving on the
/// top of the Play pile.
pub(crate) fn mad_science_variant(state: &CombatState) -> (CardType, TinkerTimeRider) {
    sts2_core::card_effects::resolving_card_inst(state).map_or(
        (CardType::Attack, TinkerTimeRider::None),
        mad_science_variant_of,
    )
}

