/// `true` iff `id` belongs to the Colorless pool (proper colorless,
/// modifier-pool entries, ancient, event neutrals, splash and the
/// pure-power colorless subset). Match over every `CardId` registered
/// in the `POOL` table above — 64 ids total at pin `01c094d`. Used by
/// relics that gate on "colorless card entered combat" (Regalite,
/// etc.). Bead `sts2-rs-70anj.5` (Regalite body-fill).
///
/// NOTE: Ancient (`Apotheosis` / `Apparition` / `BrightestFlame` /
/// `Maul` / `NeowsFury` / `Relax` / `Whistle` / `Wish`) and Event-
/// neutral (`ByrdSwoop` / `Caltrops` / `Clash` / `Distraction` /
/// `DualWield` / `Enlightenment` / `Entrench` / `Exterminate` /
/// `FeedingFrenzyCard` / `HelloWorldCard` / `MadScience` /
/// `Metamorphosis` / `Outmaneuver` / `Peck` / `Rebound` / `Squash` /
/// `Stack` / `ToricToughness`) cards live in the same dispatch POOL
/// as colorless because they're cross-character neutral cards, but
/// Python's `Regalite` gate only fires on the strict `is_colorless`
/// pool (per `sts2-rl-agent@01c094d:sts2_env/relics/uncommon.py:638`
/// — checks `card.is_colorless`, not "is in the cross-character
/// pool"). They're omitted here.
#[must_use]
pub const fn is_colorless_card_id(id: CardId) -> bool {
    matches!(
        id,
        // Colorless proper
        CardId::DarkShackles
            | CardId::Production
            | CardId::BeaconOfHope
            | CardId::Equilibrium
            | CardId::Lift
            | CardId::MayhemCard
            | CardId::TheGambit
            | CardId::Rend
            | CardId::Mimic
            | CardId::Volley
            | CardId::Jackpot
            | CardId::ThrummingHatchet
            | CardId::Stratagem
            | CardId::TagTeam
            | CardId::EternalArmor
            | CardId::NostalgiaCard
            | CardId::CalamityCard
            | CardId::RollingBoulder
            | CardId::TheBombCard
            | CardId::GoldAxe
            | CardId::GangUp
            | CardId::Catastrophe
            | CardId::JackOfAllTrades
            | CardId::BeatDown
            | CardId::Anointed
            | CardId::InterceptCard
            | CardId::SeekerStrike
            | CardId::Rally
            | CardId::Scrawl
            | CardId::BelieveInYou
            | CardId::HuddleUp
            | CardId::Knockdown
            | CardId::Entropy
            | CardId::Salvo
            // Colorless modifier pool
            | CardId::Discovery
            | CardId::DramaticEntrance
            | CardId::Finesse
            | CardId::FlashOfSteel
            | CardId::Shockwave
            | CardId::MasterOfStrategy
            | CardId::Omnislice
            | CardId::MindBlast
            | CardId::MyShinies
            | CardId::SecretTechnique
            | CardId::SecretWeapon
            | CardId::ThinkingAhead
            | CardId::Alchemize
            | CardId::HandOfGreed
            | CardId::HiddenGem
            | CardId::Fisticuffs
            | CardId::Bolas
            | CardId::PanicButton
            | CardId::Impatience
            | CardId::Prolong
            | CardId::Prowess
            | CardId::Purity
            | CardId::Restlessness
            | CardId::UltimateStrike
            | CardId::UltimateDefend
            // Pure-power colorless (atgv)
            | CardId::Automation
            | CardId::Fasten
            | CardId::PanacheCard
            | CardId::PrepTime
            | CardId::CoordinateCard
            // Splash (uncommon colorless, 9qlp)
            | CardId::Splash
    )
}

/// True iff the card's *visual card pool* is colorless — the Rust analogue
/// of C# `CardModel.VisualCardPool.IsColorless` (the gate
/// `HeirloomHammer.cs:33` and other `IsColorless` filters use).
///
/// `VisualCardPool` is the card's own pool (`CardModel.cs:325`) unless the
/// card overrides it, and `IsColorless` is a property of the pool: true for
/// the Colorless, Event, Token and Deprecated pools, false for the
/// character pools, Status, Curse and Quest (`*CardPool.cs`). Ten Event
/// cards override `VisualCardPool` with the character pool whose color they
/// wear, so they do not count: Caltrops, Distraction, Outmaneuver (Silent),
/// Clash, DualWield, Entrench (Ironclad), HelloWorld, Rebound, RipAndTear,
/// Stack (Defect) — `scripts/gen_card_pool_order.py` reads the overrides
/// from the decomp ([`crate::cards::pool_order::has_character_visual_pool`]).
/// Both the override list and the pools are the same in
/// v0.107.1 and v0.111.0, apart from the two v0.111.0-only cards
/// [`crate::cards::pool_order::in_colorless_pool`] describes.
///
/// Pool membership comes from the generated C# pool lists. The predicate
/// used to approximate them with `COLORLESS_SPECS` plus a Token/Event
/// rarity test, which missed the Ancient-rarity Event cards (Apotheosis,
/// Apparition, BrightestFlame, Maul, NeowsFury, Relax, Wish, Whistle) and
/// the Status-rarity Token cards (Disintegration, MindRot, Sloth,
/// WasteAway), and counted the ten overrides as colorless.
///
/// Bead `sts2-rs-1rv1q`: HeirloomHammer's old `is_colorless_card_id` filter
/// dropped SOVEREIGN_BLADE (a Token), so when ≥1 other colorless hand card
/// existed it cloned a DIFFERENT card than C#'s `VisualCardPool.IsColorless`
/// pick (Regent fuzz seeds 42 / 366 / 406: cloned SECRET_WEAPON/… instead
/// of the first-in-hand SOVEREIGN_BLADE).
#[must_use]
pub fn is_visual_pool_colorless(id: CardId) -> bool {
    // `public override CardPoolModel VisualCardPool => ModelDb.CardPool<..>()`
    // on these ten Event cards, generated from the decomp (#1181).
    !crate::cards::pool_order::has_character_visual_pool(id)
        && crate::cards::pool_order::in_colorless_pool(id)
}

