/// Resolve a colorless-modifier [`CardId`] to its static [`CardSpec`].
/// Returns `None` if `id` is not part of the modifier pool (the caller
/// is expected to source ids from
/// [`eligible_colorless_modifier_card_ids`] — this is a defence in
/// depth, not a graceful fallback). Bead `sts2-rs-vyh1`.
#[must_use]
pub fn colorless_modifier_spec(id: CardId) -> Option<CardSpec> {
    let spec = match id {
        CardId::Discovery => crate::cards::colorless::discovery::spec(),
        CardId::DramaticEntrance => crate::cards::colorless::dramatic_entrance::spec(),
        CardId::Finesse => crate::cards::colorless::finesse::spec(),
        CardId::FlashOfSteel => crate::cards::colorless::flash_of_steel::spec(),
        CardId::Shockwave => crate::cards::colorless::shockwave::spec(),
        CardId::MasterOfStrategy => crate::cards::colorless::master_of_strategy::spec(),
        CardId::Omnislice => crate::cards::colorless::omnislice::spec(),
        CardId::SecretTechnique => crate::cards::colorless::secret_technique::spec(),
        CardId::SecretWeapon => crate::cards::colorless::secret_weapon::spec(),
        CardId::ThinkingAhead => crate::cards::colorless::thinking_ahead::spec(),
        CardId::Alchemize => crate::cards::colorless::alchemize::spec(),
        CardId::HandOfGreed => crate::cards::colorless::hand_of_greed::spec(),
        CardId::HiddenGem => crate::cards::colorless::hidden_gem::spec(),
        CardId::Fisticuffs => crate::cards::colorless::fisticuffs::spec(),
        CardId::PanicButton => crate::cards::colorless::panic_button::spec(),
        CardId::Purity => crate::cards::colorless::purity::spec(),
        CardId::UltimateStrike => crate::cards::colorless::ultimate_strike::spec(),
        CardId::UltimateDefend => crate::cards::colorless::ultimate_defend::spec(),
        _ => return None,
    };
    Some(spec)
}

/// Sample `count` colorless modifier cards, materialise them into
/// `state.cards` (allocating fresh [`CardUid`]s) and return the new
/// uids **without** routing them into any pile. The caller chooses
/// the destination (hand / draw / discard) via
/// [`sts2_core::card_effects::spawn_card_into_hand`],
/// [`sts2_core::card_effects::spawn_card_into_pile`] etc.
///
/// Mirrors Python's
/// `create_cards_from_ids(ids, combat.rng, count, distinct=True)` at
/// `sts2-rl-agent@01c094d:sts2_env/cards/factory.py:485-500`:
///
/// * `distinct=true` draws without replacement (`rng.sample`) and caps
///   the result at `min(count, pool_len)`.
/// * `distinct=false` samples with replacement (`rng.choice` per slot)
///   and always returns exactly `count` cards.
/// * `count == 0` or an empty pool short-circuits to an empty result.
///
/// Important: the cards land in `state.cards` but in NO pile — this is
/// the Python `create_cards_from_ids` shape (returns `list[CardInstance]`
/// that the caller subsequently feeds to `move_card_to_creature_hand`
/// or `insert_card_into_creature_draw_pile`). The generated-cards
/// counter on `PlayerCombatState` (bead `sts2-rs-8h2q`) is NOT bumped
/// here — it lives on the hand-routing primitive
/// `spawn_card_into_hand`, matching Python's
/// `_add_generated_cards_to_hand` semantics.
///
/// Bead `sts2-rs-vyh1`.
pub fn create_colorless_modifier_cards(
    state: &mut CombatState,
    count: usize,
    distinct: bool,
) -> SmallVec<[CardUid; 4]> {
    let pool = eligible_colorless_modifier_card_ids();
    if count == 0 || pool.is_empty() {
        return SmallVec::new();
    }
    let chosen: SmallVec<[CardId; 4]> = if distinct {
        let take = count.min(pool.len());
        let mut shuffled: SmallVec<[CardId; 32]> = SmallVec::from_slice(pool);
        state
            .run_rng
            .combat_card_generation
            .shuffle_for(state.game_version, shuffled.as_mut_slice());
        shuffled.into_iter().take(take).collect()
    } else {
        (0..count)
            .map(|_| {
                pool[state
                    .run_rng
                    .combat_card_generation
                    .next_int_exclusive(0, pool.len() as i32) as usize]
            })
            .collect()
    };
    let mut uids: SmallVec<[CardUid; 4]> = SmallVec::with_capacity(chosen.len());
    for id in chosen {
        let spec = colorless_modifier_spec(id).expect("ids drawn from the pool resolve");
        let mut card = card_from_spec(&spec);
        let raw = u32::try_from(state.cards.len() + 1).expect("cards arena fits in u32");
        let uid = CardUid::new(raw).expect("non-zero uid");
        card.uid = uid;
        // v0.111.0 card values (GH #793).
        card.normalize_for_version(state.game_version);
        state.cards.push(card);
        uids.push(uid);
    }
    uids
}
